static const char *TAG="PRISMA_PROCESS_API";
extern const uint8_t web_process_html_start[] asm("_binary_process_html_start");
extern const uint8_t web_process_html_end[] asm("_binary_process_html_end");
static bool auth(httpd_req_t*r){return prisma_admin_authorize(r);}

static esp_err_t page_get(httpd_req_t*r){if(!auth(r))return ESP_OK;httpd_resp_set_type(r,"text/html");httpd_resp_set_hdr(r,"Cache-Control","no-store");return httpd_resp_send(r,(const char*)web_process_html_start,(ssize_t)(web_process_html_end-web_process_html_start));}

static esp_err_t send_status(httpd_req_t*r){prisma_process_status_t s={0};esp_err_t e=prisma_process_get_status(&s);if(e!=ESP_OK)return e;cJSON*j=cJSON_CreateObject();if(!j)return ESP_ERR_NO_MEM;cJSON_AddBoolToObject(j,"ready",s.ready);cJSON_AddBoolToObject(j,"busy",s.busy);cJSON_AddBoolToObject(j,"valid",s.valid);cJSON_AddStringToObject(j,"last_test",s.last_test);cJSON_AddStringToObject(j,"error",s.error);cJSON_AddNumberToObject(j,"source_width",s.source_width);cJSON_AddNumberToObject(j,"source_height",s.source_height);cJSON_AddNumberToObject(j,"width",s.width);cJSON_AddNumberToObject(j,"height",s.height);cJSON_AddNumberToObject(j,"elapsed_ms",s.elapsed_ms);cJSON_AddNumberToObject(j,"source_generation",s.source_generation);cJSON_AddNumberToObject(j,"pixel_bytes",s.pixel_bytes);cJSON_AddNumberToObject(j,"free_psram",s.free_psram);cJSON_AddNumberToObject(j,"jpeg_scale_div",s.jpeg_scale_div);char*t=cJSON_PrintUnformatted(j);cJSON_Delete(j);if(!t)return ESP_ERR_NO_MEM;httpd_resp_set_type(r,"application/json");httpd_resp_set_hdr(r,"Cache-Control","no-store");e=httpd_resp_sendstr(r,t);cJSON_free(t);return e;}

static esp_err_t run_reply(httpd_req_t*r,esp_err_t(*fn)(void),const char*f){esp_err_t e=fn();if(e==ESP_OK)return send_status(r);prisma_process_status_t s={0};(void)prisma_process_get_status(&s);if(e==ESP_ERR_NOT_FOUND)httpd_resp_set_status(r,"404 Not Found");else if(e==ESP_ERR_INVALID_STATE)httpd_resp_set_status(r,"409 Conflict");else if(e==ESP_ERR_NOT_SUPPORTED)httpd_resp_set_status(r,"415 Unsupported Media Type");else if(e==ESP_ERR_NO_MEM)httpd_resp_set_status(r,"507 Insufficient Storage");else httpd_resp_set_status(r,"500 Internal Server Error");return httpd_resp_sendstr(r,s.error[0]?s.error:f);}

static esp_err_t command_post(httpd_req_t*r){if(!auth(r))return ESP_OK;if(strcmp(r->uri,"/api/v1/process/test/poster")==0)return run_reply(r,prisma_process_run_poster,"poster failed");if(strcmp(r->uri,"/api/v1/process/test/lines")==0)return run_reply(r,prisma_process_run_lines,"lines failed");if(strcmp(r->uri,"/api/v1/process/test/rectangles")==0)return run_reply(r,prisma_process_run_rectangles,"rectangles failed");if(strcmp(r->uri,"/api/v1/process/test/circles")==0)return run_reply(r,prisma_process_run_circles,"circles failed");if(strcmp(r->uri,"/api/v1/process/test/triangles")==0)return run_reply(r,prisma_process_run_triangles,"triangles failed");httpd_resp_set_status(r,"404 Not Found");return httpd_resp_sendstr(r,"unknown processing command");}
static esp_err_t status_get(httpd_req_t*r){if(!auth(r))return ESP_OK;return send_status(r);}static esp_err_t result_get(httpd_req_t*r){if(!auth(r))return ESP_OK;esp_err_t e=prisma_process_send_bmp(r);if(e==ESP_ERR_NOT_FOUND){httpd_resp_set_status(r,"404 Not Found");return httpd_resp_sendstr(r,"No result yet");}return e;}static esp_err_t preview_get(httpd_req_t*r){if(!auth(r))return ESP_OK;esp_err_t e=prisma_process_send_preview_bmp(r);if(e==ESP_ERR_NOT_FOUND){httpd_resp_set_status(r,"404 Not Found");return httpd_resp_sendstr(r,"No 166P preview yet");}return e;}

static const char*preset_name(prisma_poster_preset_t p){switch(p){case PRISMA_POSTER_PRESET_AUTO:return"auto";case PRISMA_POSTER_PRESET_720:return"720";case PRISMA_POSTER_PRESET_480:return"480";case PRISMA_POSTER_PRESET_360:return"360";case PRISMA_POSTER_PRESET_240:return"240";case PRISMA_POSTER_PRESET_166:return"166";default:return"auto";}}
static bool parse_preset(const char*s,prisma_poster_preset_t*out){if(!s||!out)return false;if(!strcmp(s,"auto"))*out=PRISMA_POSTER_PRESET_AUTO;else if(!strcmp(s,"720"))*out=PRISMA_POSTER_PRESET_720;else if(!strcmp(s,"480"))*out=PRISMA_POSTER_PRESET_480;else if(!strcmp(s,"360"))*out=PRISMA_POSTER_PRESET_360;else if(!strcmp(s,"240"))*out=PRISMA_POSTER_PRESET_240;else if(!strcmp(s,"166"))*out=PRISMA_POSTER_PRESET_166;else return false;return true;}
static const char*aspect_name(prisma_poster_aspect_t a){switch(a){case PRISMA_POSTER_ASPECT_SOURCE:return"source";case PRISMA_POSTER_ASPECT_16_9:return"16:9";case PRISMA_POSTER_ASPECT_9_16:return"9:16";case PRISMA_POSTER_ASPECT_4_3:return"4:3";case PRISMA_POSTER_ASPECT_3_4:return"3:4";case PRISMA_POSTER_ASPECT_1_1:return"1:1";default:return"source";}}
static bool parse_aspect(const char*s,prisma_poster_aspect_t*out){if(!s||!out)return false;if(!strcmp(s,"source"))*out=PRISMA_POSTER_ASPECT_SOURCE;else if(!strcmp(s,"16:9"))*out=PRISMA_POSTER_ASPECT_16_9;else if(!strcmp(s,"9:16"))*out=PRISMA_POSTER_ASPECT_9_16;else if(!strcmp(s,"4:3"))*out=PRISMA_POSTER_ASPECT_4_3;else if(!strcmp(s,"3:4"))*out=PRISMA_POSTER_ASPECT_3_4;else if(!strcmp(s,"1:1"))*out=PRISMA_POSTER_ASPECT_1_1;else return false;return true;}

static cJSON*config_json(const prisma_poster_config_t*c){cJSON*r=cJSON_CreateObject();if(!r)return NULL;cJSON*i=cJSON_AddObjectToObject(r,"image");cJSON_AddStringToObject(i,"preset",preset_name(c->image_preset));cJSON_AddStringToObject(i,"aspect",aspect_name(c->image_aspect));cJSON*v=cJSON_AddObjectToObject(r,"video");cJSON_AddStringToObject(v,"preset",preset_name(c->video_preset));cJSON_AddStringToObject(v,"aspect",aspect_name(c->video_aspect));return r;}
static esp_err_t send_config(httpd_req_t*r,const prisma_poster_config_t*c){cJSON*j=config_json(c);if(!j)return ESP_ERR_NO_MEM;char*t=cJSON_PrintUnformatted(j);cJSON_Delete(j);if(!t)return ESP_ERR_NO_MEM;httpd_resp_set_type(r,"application/json");httpd_resp_set_hdr(r,"Cache-Control","no-store");esp_err_t e=httpd_resp_sendstr(r,t);cJSON_free(t);return e;}
static esp_err_t cfg_get(httpd_req_t*r){if(!auth(r))return ESP_OK;prisma_poster_config_t c;esp_err_t e=prisma_poster_config_load(&c);return e==ESP_OK?send_config(r,&c):e;}

static esp_err_t cfg_post(httpd_req_t*r){if(!auth(r))return ESP_OK;if(r->content_len<=0||r->content_len>511){httpd_resp_set_status(r,"400 Bad Request");return httpd_resp_sendstr(r,"invalid config body");}char b[512];size_t o=0;while(o<(size_t)r->content_len){int n=httpd_req_recv(r,b+o,(size_t)r->content_len-o);if(n==HTTPD_SOCK_ERR_TIMEOUT)continue;if(n<=0)return ESP_FAIL;o+=(size_t)n;}b[o]='\0';cJSON*j=cJSON_Parse(b);if(!j){httpd_resp_set_status(r,"400 Bad Request");return httpd_resp_sendstr(r,"invalid JSON");}prisma_poster_config_t c;(void)prisma_poster_config_load(&c);cJSON*i=cJSON_GetObjectItemCaseSensitive(j,"image"),*v=cJSON_GetObjectItemCaseSensitive(j,"video");bool ok=true;if(cJSON_IsObject(i)){cJSON*p=cJSON_GetObjectItemCaseSensitive(i,"preset"),*a=cJSON_GetObjectItemCaseSensitive(i,"aspect");if(cJSON_IsString(p))ok&=parse_preset(p->valuestring,&c.image_preset);if(cJSON_IsString(a))ok&=parse_aspect(a->valuestring,&c.image_aspect);}if(cJSON_IsObject(v)){cJSON*p=cJSON_GetObjectItemCaseSensitive(v,"preset"),*a=cJSON_GetObjectItemCaseSensitive(v,"aspect");if(cJSON_IsString(p))ok&=parse_preset(p->valuestring,&c.video_preset);if(cJSON_IsString(a))ok&=parse_aspect(a->valuestring,&c.video_aspect);}cJSON_Delete(j);if(!ok||!prisma_poster_config_valid(&c)){httpd_resp_set_status(r,"400 Bad Request");return httpd_resp_sendstr(r,"invalid preset/aspect");}esp_err_t e=prisma_poster_config_save(&c);if(e!=ESP_OK)return e;(void)prisma_processed_invalidate(PRISMA_PROCESSED_IMAGE_OUT);(void)prisma_processed_invalidate(PRISMA_PROCESSED_IMAGE_PREVIEW);(void)prisma_processed_invalidate(PRISMA_PROCESSED_VIDEO_OUT);(void)prisma_processed_invalidate(PRISMA_PROCESSED_VIDEO_PREVIEW);return send_config(r,&c);}

static void reg(httpd_handle_t s,const httpd_uri_t*u){esp_err_t e=httpd_register_uri_handler(s,u);if(e!=ESP_OK)ESP_LOGE(TAG,"route %s failed: %s",u->uri,esp_err_to_name(e));}
void prisma_process_register_routes(httpd_handle_t s){(void)prisma_process_init();static const httpd_uri_t page={.uri="/admin/process",.method=HTTP_GET,.handler=page_get};static const httpd_uri_t cmd={.uri="/api/v1/process/test/*",.method=HTTP_POST,.handler=command_post};static const httpd_uri_t st={.uri="/api/v1/process/test/status",.method=HTTP_GET,.handler=status_get};static const httpd_uri_t res={.uri="/api/v1/process/test/result.bmp",.method=HTTP_GET,.handler=result_get};static const httpd_uri_t pre={.uri="/api/v1/process/test/preview166.bmp",.method=HTTP_GET,.handler=preview_get};static const httpd_uri_t cg={.uri="/api/v1/poster/config",.method=HTTP_GET,.handler=cfg_get};static const httpd_uri_t cp={.uri="/api/v1/poster/config",.method=HTTP_POST,.handler=cfg_post};reg(s,&page);reg(s,&cmd);reg(s,&st);reg(s,&res);reg(s,&pre);reg(s,&cg);reg(s,&cp);prisma_video_process_register_routes(s);ESP_LOGI(TAG,"CORE-5A PRISMA-PI processing routes ready");}
